using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseLogging()
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

builder.Logging.SetMinimumLevel(LogLevel.Warning);

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the SearchWeb tool to find relevant information (make 2-3 searches with different queries).
        2. Use SaveNote to record key findings as you go.
        3. Use GetNotes to review everything you've collected.
        4. Provide a well-structured summary with key facts, organized by theme.
        Be thorough but concise. Cite the sources you found.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics using web search and note-taking tools",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"\nResearching \"{topic}\"...\n");
    Console.ResetColor();

    var session = await agent.CreateSessionAsync();

    var response = await agent.RunAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        session,
        new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            },
        });

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();

    if (response.Usage is { } usage)
    {
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"\n[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ── Tool implementations ─────────────────────────────────────────────

public sealed class Notepad
{
    private readonly List<string> _notes = [];
    private readonly Lock _lock = new();

    public void Add(string note)
    {
        lock (_lock) _notes.Add(note);
    }

    public IReadOnlyList<string> GetAll()
    {
        lock (_lock) return [.. _notes];
    }

    public void Clear()
    {
        lock (_lock) _notes.Clear();
    }
}

public sealed class ResearchTools(Notepad notepad)
{
    [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public string SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing Search, Google Custom Search, etc.) for production use.
        var results = GenerateSimulatedResults(query);
        var sb = new StringBuilder();
        sb.AppendLine($"Search results for: \"{query}\"\n");
        foreach (var (title, snippet, url) in results)
        {
            sb.AppendLine($"• {title}");
            sb.AppendLine($"  {snippet}");
            sb.AppendLine($"  Source: {url}");
            sb.AppendLine();
        }
        return sb.ToString();
    }

    [Description("Save a research note for later reference. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("The note content to save")] string content)
    {
        notepad.Add(content);
        return $"Note saved. You now have {notepad.GetAll().Count} note(s).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        var notes = notepad.GetAll();
        if (notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Saved notes ({notes.Count}):\n");
        for (var i = 0; i < notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {notes[i]}\n");
        return sb.ToString();
    }

    public void ClearNotes() => notepad.Clear();

    private static List<(string Title, string Snippet, string Url)> GenerateSimulatedResults(string query)
    {
        var hash = Math.Abs(query.GetHashCode());
        var domains = new[] { "en.wikipedia.org", "nature.com", "arxiv.org", "sciencedaily.com", "reuters.com" };
        var results = new List<(string, string, string)>();

        for (var i = 0; i < 3; i++)
        {
            var domain = domains[(hash + i) % domains.Length];
            results.Add((
                $"{query} - Overview and Key Facts (Source {i + 1})",
                $"This article covers the latest developments in {query.ToLowerInvariant()}. "
                + $"Key findings include recent advances, ongoing challenges, and future directions in the field. "
                + $"Experts note significant progress in the past decade.",
                $"https://{domain}/article/{Uri.EscapeDataString(query.ToLowerInvariant().Replace(' ', '-'))}-{hash + i}"
            ));
        }

        return results;
    }
}

