+public sealed class Notepad
+{
+    private readonly List<string> _notes = [];
+    private readonly Lock _lock = new();
+
+    public void Add(string note)
+    {
+        lock (_lock) _notes.Add(note);
+    }
+
+    public IReadOnlyList<string> GetAll()
+    {
+        lock (_lock) return [.. _notes];
+    }
+
+    public void Clear()
+    {
+        lock (_lock) _notes.Clear();
+    }
+}
+
+public sealed class ResearchTools(Notepad notepad)
+{
+    [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
+    public string SearchWeb(
+        [Description("The search query to look up")] string query)
+    {
+        // Simulated web search results for demonstration.
+        // Replace with a real search API (Bing Search, Google Custom Search, etc.) for production use.
+        var results = GenerateSimulatedResults(query);
+        var sb = new StringBuilder();
+        sb.AppendLine($"Search results for: \"{query}\"\n");
+        foreach (var (title, snippet, url) in results)
+        {
+            sb.AppendLine($"• {title}");
+            sb.AppendLine($"  {snippet}");
+            sb.AppendLine($"  Source: {url}");
+            sb.AppendLine();
+        }
+        return sb.ToString();
+    }
+
+    [Description("Save a research note for later reference. Use this to record key findings during research.")]
+    public string SaveNote(
+        [Description("The note content to save")] string content)
+    {
+        notepad.Add(content);
+        return $"Note saved. You now have {notepad.GetAll().Count} note(s).";
+    }
+
+    [Description("Retrieve all saved research notes collected so far.")]
+    public string GetNotes()
+    {
+        var notes = notepad.GetAll();
+        if (notes.Count == 0)
+            return "No notes saved yet.";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"Saved notes ({notes.Count}):\n");
+        for (var i = 0; i < notes.Count; i++)
+            sb.AppendLine($"[{i + 1}] {notes[i]}\n");
+        return sb.ToString();
+    }
+
+    public void ClearNotes() => notepad.Clear();
+
+    private static List<(string Title, string Snippet, string Url)> GenerateSimulatedResults(string query)
+    {
+        var hash = Math.Abs(query.GetHashCode());
+        var domains = new[] { "en.wikipedia.org", "nature.com", "arxiv.org", "sciencedaily.com", "reuters.com" };
+        var results = new List<(string, string, string)>();
+
+        for (var i = 0; i < 3; i++)
+        {
+            var domain = domains[(hash + i) % domains.Length];
+            results.Add((
+                $"{query} - Overview and Key Facts (Source {i + 1})",
+                $"This article covers the latest developments in {query.ToLowerInvariant()}. "
+                + $"Key findings include recent advances, ongoing challenges, and future directions in the field. "
+                + $"Experts note significant progress in the past decade.",
+                $"https://{domain}/article/{Uri.EscapeDataString(query.ToLowerInvariant().Replace(' ', '-'))}-{hash + i}"
+            ));
+        }
+
+        return results;
+    }
